"use strict";
import Highcharts from "highcharts";
import HighchartsReact from "highcharts-react-official";
import { useMorphoMarketHistory } from "hooks/morpho";
import { useMemo, useState } from "react";
import { ArrowUpRight, BarChart2, DollarSign } from "react-feather";
import { Flex, SpinningLoader, Text, styled as uiStyled, useSporeColors } from "ui/src";
import { Sparkle } from "ui/src/components/icons";
import { useMarketContext } from "../../ContextProvider";
import { Badge, ChartContainer, HeaderRow, ValueText } from "../ChartProperties";
import TimeDropdown from "../TimeDropdown";
function timeRangeToDays(range) {
  switch (range) {
    case "All time":
      return 365;
    case "3 months":
      return 90;
    case "1 month":
      return 30;
    case "1 week":
      return 7;
    default:
      return 90;
  }
}
const DetailsCard = uiStyled(Flex, {
  flexDirection: "column",
  backgroundColor: "$surface2",
  borderRadius: "$rounded16",
  padding: "$spacing24",
  minWidth: 300,
  gap: "$spacing16"
});
const DetailRow = uiStyled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%"
});
const Divider = uiStyled(Flex, {
  height: 1,
  width: "100%",
  backgroundColor: "$surface3",
  marginVertical: "$spacing8"
});
export default function RateChart() {
  const colors = useSporeColors();
  const { marketId, chainId, marketData } = useMarketContext();
  const [timeRange, setTimeRange] = useState("1 month");
  const days = timeRangeToDays(timeRange);
  const { data: historyData, isLoading } = useMorphoMarketHistory(marketId ?? void 0, chainId, days);
  const chartData = useMemo(() => {
    if (!historyData || historyData.length === 0) return [];
    return historyData.map((point) => [point.timestamp * 1e3, point.borrowAPY]);
  }, [historyData]);
  const currentRate = useMemo(() => {
    if (!historyData || historyData.length === 0) return marketData?.borrowRate ?? 0;
    return historyData[historyData.length - 1].borrowAPY;
  }, [historyData, marketData]);
  const averageRate = useMemo(() => {
    if (!historyData || historyData.length === 0) return currentRate;
    const sum = historyData.reduce((acc, point) => acc + point.borrowAPY, 0);
    return sum / historyData.length;
  }, [historyData, currentRate]);
  const options = useMemo(
    () => ({
      chart: {
        type: "area",
        backgroundColor: "transparent",
        height: 250,
        margin: [0, 50, 30, 0],
        style: { fontFamily: "Inter, sans-serif" }
      },
      title: { text: void 0 },
      legend: { enabled: false },
      credits: { enabled: false },
      xAxis: {
        visible: true,
        lineColor: "transparent",
        tickColor: "transparent",
        labels: {
          style: { color: colors.neutral3.val, fontSize: "10px" },
          format: "{value:%d %b}"
        },
        type: "datetime"
      },
      yAxis: {
        visible: true,
        gridLineColor: "transparent",
        opposite: true,
        labels: {
          style: { color: colors.neutral3.val, fontSize: "10px" },
          format: "{value}%"
        },
        plotLines: [
          {
            color: "#4C82FB",
            width: 1,
            value: averageRate,
            dashStyle: "Dash",
            zIndex: 5,
            label: {
              text: `Avg ${averageRate.toFixed(2)}%`,
              align: "left",
              style: {
                color: colors.neutral3.val,
                fontSize: "10px"
              },
              x: 0,
              y: -5
            }
          }
        ]
      },
      tooltip: {
        backgroundColor: colors.surface1.val,
        borderColor: colors.surface3.val,
        borderRadius: 8,
        style: { color: colors.neutral1.val },
        padding: 12,
        shadow: true,
        className: "chart-tooltip",
        formatter: function() {
          return `
              <div style="display: flex; flex-direction: column; align-items: center;">
                <span style="font-size: 10px; color: ${colors.neutral2.val}; margin-bottom: 4px;">
                  ${Highcharts.dateFormat("%d %b", this.x)}
                </span>
                <span style="font-size: 12px; font-weight: 600; color: ${colors.neutral1.val};">
                  ${this.y?.toFixed(2)}%
                </span>
              </div>
            `;
        },
        useHTML: true
      },
      plotOptions: {
        area: {
          fillColor: {
            linearGradient: { x1: 0, y1: 0, x2: 0, y2: 1 },
            stops: [
              [0, "rgba(76, 130, 251, 0.2)"],
              [1, "rgba(76, 130, 251, 0)"]
            ]
          },
          lineColor: "#4C82FB",
          lineWidth: 2,
          marker: { radius: 0, states: { hover: { enabled: true, radius: 4 } } },
          threshold: null
        }
      },
      series: [
        {
          type: "area",
          name: "APY",
          data: chartData
        }
      ]
    }),
    [colors, chartData, averageRate]
  );
  return <ChartContainer>
      <Flex flexDirection="row" gap="$spacing24" flexWrap="wrap">
        <Flex flexDirection="column" style={{ flex: 1, minWidth: 300 }}>
          <HeaderRow $md={{ flexDirection: "row" }}>
            <Flex flexDirection="row" alignItems="center" gap="$gap4">
              <Text variant="body3" color="$neutral2">
                Rate
              </Text>
              <Sparkle size={16} color={colors.neutral2.val} />
            </Flex>
            <TimeDropdown value={timeRange} onChange={setTimeRange} />
          </HeaderRow>

          {isLoading ? <Flex py="$spacing24" alignItems="center" justifyContent="center">
              <SpinningLoader size={24} />
            </Flex> : <>
              <ValueText>{currentRate.toFixed(2)}%</ValueText>
              <HighchartsReact highcharts={Highcharts} options={options} />
            </>}
        </Flex>

        <DetailsCard>
          <DetailRow>
            <Flex flexDirection="row" alignItems="center" gap="$gap8">
              <BarChart2 size={16} color={colors.neutral2.val} />
              <Text variant="body2" color="$neutral2">
                Native APY
              </Text>
            </Flex>
            <Text variant="body2" color="$neutral1">
              {currentRate.toFixed(2)}%
            </Text>
          </DetailRow>

          <DetailRow>
            <Flex flexDirection="row" alignItems="center" gap="$gap8">
              <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: "#007AFF" }} />
              <Text variant="body2" color="$neutral2">
                MORPHO
              </Text>
              <ArrowUpRight size={12} color={colors.neutral2.val} />
            </Flex>
            <Text variant="body2" color="$neutral1">
              --
            </Text>
          </DetailRow>

          <DetailRow>
            <Flex flexDirection="row" alignItems="center" gap="$gap8">
              <DollarSign size={16} color={colors.neutral2.val} />
              <Text variant="body2" color="$neutral2">
                Performance Fee
              </Text>
              <Badge>
                <Text variant="body2" color="$neutral2">
                  0%
                </Text>
              </Badge>
            </Flex>
            <Text variant="body2" color="$neutral1">
              --
            </Text>
          </DetailRow>

          <Divider />

          <DetailRow>
            <Flex flexDirection="row" alignItems="center" gap="$gap8">
              <Sparkle size={16} color={colors.neutral2.val} />
              <Text variant="body2" color="#4C82FB">
                Net APY
              </Text>
            </Flex>
            <Text variant="body2" color="#4C82FB">
              {currentRate.toFixed(2)}%
            </Text>
          </DetailRow>
        </DetailsCard>
      </Flex>
    </ChartContainer>;
}
