"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { Flex, Text } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { useMarketContext } from "../../ContextProvider";
import GridItem from "../GridItem";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { formatPriceWithSignificantDigits } from "../../utils/healthFactorUtils";
const TokenInfoWithAmount = ({
  tokenSymbol,
  tokenAddress,
  amount,
  amountUsd,
  chainId
}) => {
  const { formatFiatPrice, formatNumber } = useFormatter();
  return <Flex row alignItems="center" gap={"$gap8"}>
      <PortfolioLogo
    chainId={chainId}
    tokenSymbol={tokenSymbol}
    images={[getTokenLogoUrl(tokenAddress)]}
    size={18}
  />
      <Text variant="body2" $sm={{ variant: "body3" }} color="$neutral1">
        {formatNumber({ input: Number(amount), type: NumberType.TokenTx })} {tokenSymbol}
      </Text>
      <Flex px={"$spacing8"} backgroundColor={"$surface2"} borderRadius={"$rounded20"}>
        <Text variant="body4">{formatFiatPrice({ price: amountUsd, type: NumberType.FiatTokenStats })}</Text>
      </Flex>
    </Flex>;
};
export default function PositionGridItems() {
  const { marketData, userPosition, chainId } = useMarketContext();
  if (!marketData) {
    return null;
  }
  const hasPosition = userPosition && Number(userPosition.collateralFormatted) > 0;
  const collateralAmount = userPosition?.collateralFormatted ?? "0";
  const collateralUsd = userPosition?.collateralUsd ?? 0;
  const borrowAmount = userPosition?.borrowAssetsFormatted ?? "0";
  const borrowUsd = userPosition?.borrowAssetsUsd ?? 0;
  const ltv = userPosition?.ltv ?? 0;
  const lltvPercent = marketData.lltvPercent;
  const liquidationPrice = userPosition?.liquidationPrice ?? 0;
  const healthFactor = userPosition?.healthFactor ?? 0;
  const dropToLiquidation = hasPosition && ltv > 0 ? Math.max(0, (lltvPercent - ltv) / lltvPercent * 100) : 0;
  return <Flex
    $platform-web={{ display: "grid", gridTemplateColumns: "1fr 1fr" }}
    $lg={{ gridTemplateColumns: "1fr" }}
    gap="$gap24"
    mt={"$spacing24"}
  >
      <Flex className="left-items">
        <GridItem
    label="Collateral"
    component={<TokenInfoWithAmount
      tokenSymbol={marketData.collateralToken.symbol}
      tokenAddress={marketData.collateralToken.address}
      amount={collateralAmount}
      amountUsd={collateralUsd}
      chainId={chainId}
    />}
  />
        <GridItem
    label="Loan"
    component={<TokenInfoWithAmount
      tokenSymbol={marketData.loanToken.symbol}
      tokenAddress={marketData.loanToken.address}
      amount={borrowAmount}
      amountUsd={borrowUsd}
      chainId={chainId}
    />}
  />
        <GridItem
    label="LTV / Liquidation LTV"
    value={hasPosition ? `${ltv.toFixed(1)}% / ${lltvPercent}%` : `- / ${lltvPercent}%`}
  />
      </Flex>

      <Flex className="right-items">
        <GridItem
    label="Liquidation price"
    value={hasPosition && liquidationPrice > 0 ? `$${formatPriceWithSignificantDigits(liquidationPrice)}` : "-"}
  />
        <GridItem
    label="% drop to liquidation"
    value={hasPosition ? `${dropToLiquidation.toFixed(2)}%` : "-"}
  />
        <GridItem
    label="Health Factor"
    value={hasPosition ? healthFactor === Infinity || !isFinite(healthFactor) ? "\u221E" : healthFactor.toFixed(2) : "-"}
  />
      </Flex>
    </Flex>;
}
