"use strict";
import { PortfolioLogo } from "components/AccountDrawer/MiniPortfolio/PortfolioLogo";
import { useMorphoUserBorrowPosition } from "hooks/morpho";
import { useState } from "react";
import { ArrowRight, Shield } from "react-feather";
import { Button, Flex, Input, SpinningLoader, Text, styled, useSporeColors } from "ui/src";
import { getTokenLogoUrl } from "uniswap/src/constants/tokenLogos";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useAccount } from "wagmi";
import BorrowConfirmModal from "../components/BorrowConfirmModal";
import BorrowReviewModal from "../components/BorrowReviewModal";
import { calculateProjectedHealthFactor } from "./utils/healthFactorUtils";
const Container = styled(Flex, {
  flexDirection: "column",
  gap: "$spacing12",
  width: "100%",
  maxWidth: 480,
  "$platform-web": {
    position: "sticky",
    top: "100px"
  }
});
const TabContainer = styled(Flex, {
  flexDirection: "row",
  gap: "$spacing8",
  marginBottom: "$spacing8"
});
const TabButton = styled(Button, {
  backgroundColor: "transparent",
  borderRadius: "$roundedFull",
  paddingVertical: "$spacing8",
  paddingHorizontal: "$spacing16",
  borderWidth: 0,
  variants: {
    active: {
      true: {
        backgroundColor: "$surface3",
        color: "$neutral1"
      },
      false: {
        backgroundColor: "transparent",
        color: "$neutral2",
        hoverStyle: {
          backgroundColor: "$surface2"
        }
      }
    }
  }
});
const Card = styled(Flex, {
  backgroundColor: "$surface2",
  borderRadius: "$rounded20",
  py: "$spacing16",
  px: "$spacing16",
  flexDirection: "column",
  gap: "$spacing8",
  position: "relative",
  borderWidth: 1,
  borderColor: "$surface3",
  transition: "border-color 0.2s ease-in-out",
  variants: {
    focused: {
      true: {
        borderColor: "$neutral3"
      }
    }
  }
});
const InputField = styled(Input, {
  unstyled: true,
  backgroundColor: "transparent",
  borderWidth: 0,
  outlineStyle: "none",
  padding: 0,
  fontSize: "36px",
  fontWeight: "400",
  color: "$neutral1",
  width: "100%",
  textAlign: "left",
  placeholderTextColor: "$neutral3",
  height: "auto",
  lineHeight: "56px",
  fontFamily: "$body"
});
const MaxButton = styled(Flex, {
  backgroundColor: "$surface3",
  borderRadius: "$rounded8",
  paddingVertical: "$spacing4",
  paddingHorizontal: "$spacing8",
  cursor: "pointer",
  hoverStyle: { opacity: 0.8 }
});
const InfoRow = styled(Flex, {
  flexDirection: "row",
  justifyContent: "space-between",
  alignItems: "center",
  width: "100%",
  marginBottom: "$spacing4"
});
const ActionButton = styled(Button, {
  width: "100%",
  borderRadius: "$rounded20",
  py: "$spacing24",
  marginTop: "$spacing8",
  variants: {
    disabled: {
      true: {
        backgroundColor: "$surface3",
        color: "$neutral2",
        cursor: "not-allowed"
      },
      false: {
        backgroundColor: "$accent1",
        color: "$white",
        hoverStyle: { backgroundColor: "$accent1Hovered" },
        pressStyle: { backgroundColor: "$accent1Pressed" }
      }
    }
  }
});
const ShieldIcon = styled(Flex, {
  backgroundColor: "$surface4",
  borderRadius: "$roundedFull",
  width: 20,
  height: 20,
  alignItems: "center",
  justifyContent: "center",
  marginLeft: "$spacing4"
});
export default function BorrowRepayInterface({ marketData }) {
  const [activeTab, setActiveTab] = useState("borrow");
  const [collateralAmount, setCollateralAmount] = useState("");
  const [borrowAmount, setBorrowAmount] = useState("");
  const [focusedInput, setFocusedInput] = useState(null);
  const [isReviewOpen, setIsReviewOpen] = useState(false);
  const [isConfirmOpen, setIsConfirmOpen] = useState(false);
  const colors = useSporeColors();
  const chainId = UniverseChainId.Mainnet;
  const { address: userAddress } = useAccount();
  const isBorrow = activeTab === "borrow";
  const { data: userPosition, isLoading: isLoadingPosition } = useMorphoUserBorrowPosition(
    marketData.id,
    userAddress,
    chainId
  );
  const collateralToken = {
    symbol: marketData.collateralToken.symbol,
    id: marketData.collateralToken.address,
    price: marketData.collateralPriceUsd
  };
  const borrowToken = {
    symbol: marketData.loanToken.symbol,
    id: marketData.loanToken.address,
    price: marketData.loanPriceUsd
  };
  const collateralWalletBalanceRaw = userPosition?.walletCollateralBalanceFormatted ?? "0";
  const borrowWalletBalanceRaw = userPosition?.walletLoanBalanceFormatted ?? "0";
  const existingCollateralRaw = userPosition?.collateralFormatted ?? "0";
  const existingLoanRaw = userPosition?.borrowAssetsFormatted ?? "0";
  const collateralWalletBalance = Number(collateralWalletBalanceRaw);
  const borrowWalletBalance = Number(borrowWalletBalanceRaw);
  const existingCollateral = Number(existingCollateralRaw);
  const existingLoan = Number(existingLoanRaw);
  const liquidationLtv = marketData.lltvPercent;
  const rate = marketData.borrowRate;
  const parsedCollateral = parseFloat(collateralAmount) || 0;
  const parsedBorrow = parseFloat(borrowAmount) || 0;
  const collateralUsd = parsedCollateral * marketData.collateralPriceUsd;
  const borrowUsd = parsedBorrow * marketData.loanPriceUsd;
  const totalCollateral = isBorrow ? existingCollateral + parsedCollateral : Math.max(0, existingCollateral - parsedCollateral);
  const totalBorrow = isBorrow ? existingLoan + parsedBorrow : Math.max(0, existingLoan - parsedBorrow);
  const totalCollateralUsd = totalCollateral * marketData.collateralPriceUsd;
  const totalBorrowUsd = totalBorrow * marketData.loanPriceUsd;
  const projectedLtv = totalCollateralUsd > 0 ? totalBorrowUsd / totalCollateralUsd * 100 : 0;
  const currentLtv = userPosition?.ltv ?? 0;
  const currentHealthFactor = userPosition?.healthFactor ?? Infinity;
  const projectedHealthFactor = calculateProjectedHealthFactor(
    existingCollateral,
    parsedCollateral,
    existingLoan,
    parsedBorrow,
    marketData.collateralPriceUsd,
    marketData.loanPriceUsd,
    marketData.lltvPercent,
    !isBorrow
  );
  const isFormValid = parsedCollateral > 0 || parsedBorrow > 0;
  const availableLiquidity = Number(marketData.availableLiquidityFormatted);
  const canBorrowOnly = existingCollateral > 0 && parsedCollateral === 0 && parsedBorrow > 0;
  const hasInsufficientCollateral = !canBorrowOnly && parsedBorrow > 0 && parsedCollateral === 0 && existingCollateral === 0;
  const maxBorrowableByCollateral = (() => {
    const totalCollateralAfter = existingCollateral + parsedCollateral;
    const collateralValueUsd = totalCollateralAfter * marketData.collateralPriceUsd;
    const maxBorrowUsd = collateralValueUsd * (marketData.lltvPercent / 100) * 0.95;
    const maxBorrowAmount = maxBorrowUsd / marketData.loanPriceUsd - existingLoan;
    return Math.max(0, maxBorrowAmount);
  })();
  const maxBorrowable = Math.min(maxBorrowableByCollateral, availableLiquidity);
  const maxWithdrawableCollateral = (() => {
    const remainingLoanAfterRepay = Math.max(0, existingLoan - parsedBorrow);
    if (remainingLoanAfterRepay === 0) return existingCollateral;
    const requiredCollateralValueUsd = remainingLoanAfterRepay * marketData.loanPriceUsd / (marketData.lltvPercent / 100) / 0.95;
    const requiredCollateral = requiredCollateralValueUsd / marketData.collateralPriceUsd;
    return Math.max(0, existingCollateral - requiredCollateral);
  })();
  const supplyExceedsBalance = isBorrow && parsedCollateral > collateralWalletBalance;
  const borrowExceedsLiquidity = isBorrow && parsedBorrow > availableLiquidity;
  const borrowExceedsCollateralLimit = isBorrow && parsedBorrow > maxBorrowableByCollateral;
  const borrowExceedsMax = borrowExceedsLiquidity || borrowExceedsCollateralLimit;
  const repayExceedsBalance = !isBorrow && parsedBorrow > borrowWalletBalance;
  const repayExceedsLoan = !isBorrow && parsedBorrow > existingLoan;
  const withdrawExceedsCollateral = !isBorrow && parsedCollateral > existingCollateral;
  const withdrawExceedsAllowed = !isBorrow && parsedCollateral > maxWithdrawableCollateral;
  const hasValidationError = supplyExceedsBalance || borrowExceedsMax || hasInsufficientCollateral || repayExceedsBalance || repayExceedsLoan || withdrawExceedsCollateral || withdrawExceedsAllowed;
  const getValidationError = () => {
    if (isBorrow) {
      if (supplyExceedsBalance) return { message: `Insufficient ${collateralToken.symbol} balance`, type: "critical" };
      if (hasInsufficientCollateral) return { message: "Add collateral to enable borrowing", type: "critical" };
      if (borrowExceedsLiquidity) return { message: `Only ${availableLiquidity.toFixed(4)} ${borrowToken.symbol} available in market`, type: "warning" };
      if (borrowExceedsCollateralLimit) return { message: `Max borrowable: ${maxBorrowableByCollateral.toFixed(4)} ${borrowToken.symbol}`, type: "warning" };
    } else {
      if (repayExceedsBalance) return { message: `Insufficient ${borrowToken.symbol} balance`, type: "critical" };
      if (repayExceedsLoan) return { message: `Cannot repay more than outstanding loan (${existingLoan.toFixed(4)} ${borrowToken.symbol})`, type: "warning" };
      if (withdrawExceedsCollateral) return { message: `Cannot withdraw more than deposited collateral`, type: "critical" };
      if (withdrawExceedsAllowed) return { message: `Max withdrawable: ${maxWithdrawableCollateral.toFixed(4)} ${collateralToken.symbol}`, type: "warning" };
    }
    return null;
  };
  const validationError = getValidationError();
  const getActionText = () => {
    if (!isFormValid) return "Enter an amount";
    if (isBorrow) {
      const hasCollateral = parsedCollateral > 0;
      const hasBorrow = parsedBorrow > 0;
      if (hasCollateral && hasBorrow) return "Supply & Borrow";
      if (hasCollateral) return "Supply Collateral";
      if (hasBorrow) return "Borrow";
    } else {
      const hasRepay = parsedBorrow > 0;
      const hasWithdraw = parsedCollateral > 0;
      if (hasRepay && hasWithdraw) return "Repay & Withdraw";
      if (hasRepay) return "Repay Loan";
      if (hasWithdraw) return "Withdraw Collateral";
    }
    return "Enter an amount";
  };
  const actionText = getActionText();
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setCollateralAmount("");
    setBorrowAmount("");
  };
  const handleConfirm = () => {
    setIsReviewOpen(false);
    setIsConfirmOpen(true);
  };
  return <Container>
      {
    /* Tabs */
  }
      <TabContainer>
        <TabButton active={activeTab === "borrow"} onPress={() => handleTabChange("borrow")}>
          <Text variant="buttonLabel2" color={activeTab === "borrow" ? "$neutral1" : "$neutral2"}>
            Borrow
          </Text>
        </TabButton>
        <TabButton active={activeTab === "repay"} onPress={() => handleTabChange("repay")}>
          <Text variant="buttonLabel2" color={activeTab === "repay" ? "$neutral1" : "$neutral2"}>
            Repay
          </Text>
        </TabButton>
      </TabContainer>

      {
    /* First Card: Supply Collateral (borrow) or Repay Loan (repay) */
  }
      <Card focused={focusedInput === "first"}>
        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text variant="body3" color="$neutral2">
            {isBorrow ? `Supply Collateral ${collateralToken.symbol}` : `Repay ${borrowToken.symbol}`}
          </Text>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={isBorrow ? collateralToken.symbol : borrowToken.symbol}
    tokenName={isBorrow ? collateralToken.symbol : borrowToken.symbol}
    images={[getTokenLogoUrl(isBorrow ? collateralToken.id : borrowToken.id)]}
    size={20}
  />
        </Flex>

        <InputField
    placeholder="0.00"
    value={isBorrow ? collateralAmount : borrowAmount}
    onChangeText={isBorrow ? setCollateralAmount : setBorrowAmount}
    placeholderTextColor="$neutral3"
    onFocus={() => setFocusedInput("first")}
    onBlur={() => setFocusedInput(null)}
  />

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mt="$spacing4">
          <Text variant="body4" color={(isBorrow ? collateralUsd : borrowUsd) > 0 ? "$neutral1" : "$neutral3"}>
            ${(isBorrow ? collateralUsd : borrowUsd).toFixed(2)}
          </Text>
          <Flex flexDirection="row" gap="$gap8" alignItems="center">
            {isLoadingPosition ? <SpinningLoader size={16} /> : <Text variant="body4" color="$neutral2">
                {isBorrow ? `${collateralWalletBalance.toFixed(4)} ${collateralToken.symbol}` : `${borrowWalletBalance.toFixed(4)} ${borrowToken.symbol}`}
              </Text>}
            <MaxButton
    onPress={() => {
      if (isBorrow) {
        setCollateralAmount(collateralWalletBalanceRaw);
      } else {
        const useWalletBalance = borrowWalletBalance <= existingLoan;
        setBorrowAmount(useWalletBalance ? borrowWalletBalanceRaw : existingLoanRaw);
      }
    }}
  >
              <Text variant="buttonLabel4" color="$neutral2">
                MAX
              </Text>
            </MaxButton>
          </Flex>
        </Flex>
      </Card>

      {
    /* Second Card: Borrow (borrow) or Withdraw Collateral (repay) */
  }
      <Card focused={focusedInput === "second"}>
        <Flex flexDirection="row" justifyContent="space-between" alignItems="center">
          <Text variant="body3" color="$neutral2">
            {isBorrow ? `Borrow ${borrowToken.symbol}` : `Withdraw Collateral ${collateralToken.symbol}`}
          </Text>
          <PortfolioLogo
    chainId={UniverseChainId.Mainnet}
    tokenSymbol={isBorrow ? borrowToken.symbol : collateralToken.symbol}
    tokenName={isBorrow ? borrowToken.symbol : collateralToken.symbol}
    images={[getTokenLogoUrl(isBorrow ? borrowToken.id : collateralToken.id)]}
    size={20}
  />
        </Flex>

        <InputField
    placeholder="0.00"
    value={isBorrow ? borrowAmount : collateralAmount}
    onChangeText={isBorrow ? setBorrowAmount : setCollateralAmount}
    placeholderTextColor="$neutral3"
    onFocus={() => setFocusedInput("second")}
    onBlur={() => setFocusedInput(null)}
  />

        <Flex flexDirection="row" justifyContent="space-between" alignItems="center" mt="$spacing4">
          <Text variant="body4" color="$neutral3">
            ${(isBorrow ? borrowUsd : collateralUsd).toFixed(2)}
          </Text>
          <Flex flexDirection="row" gap="$gap8" alignItems="center">
            {isLoadingPosition ? <SpinningLoader size={16} /> : <Text variant="body4" color="$neutral2">
                {isBorrow ? `${borrowWalletBalance.toFixed(4)} ${borrowToken.symbol}` : `${existingCollateral.toFixed(4)} ${collateralToken.symbol}`}
              </Text>}
            <MaxButton
    onPress={() => {
      if (isBorrow) {
        if (maxBorrowable > 0) {
          const conservativeMax = Math.floor(maxBorrowable * 1e6) / 1e6;
          setBorrowAmount(conservativeMax.toFixed(6));
        }
      } else {
        const safeMaxWithdraw = Math.min(existingCollateral, maxWithdrawableCollateral);
        if (safeMaxWithdraw > 0) {
          const conservativeMax = Math.floor(safeMaxWithdraw * 1e6) / 1e6;
          setCollateralAmount(conservativeMax.toFixed(6));
        }
      }
    }}
  >
              <Text variant="buttonLabel4" color="$neutral2">
                MAX
              </Text>
            </MaxButton>
          </Flex>
        </Flex>
      </Card>

      {
    /* Info Card */
  }
      <Card>
        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={chainId}
    tokenSymbol={collateralToken.symbol}
    tokenName={collateralToken.symbol ?? ""}
    images={[getTokenLogoUrl(collateralToken.id)]}
    size={20}
  />
            <Text variant="body3" color="$neutral2">
              Collateral ({collateralToken.symbol})
            </Text>
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body3" color="$neutral2">
              {existingCollateral.toFixed(4)}
            </Text>
            {parsedCollateral > 0 && <ArrowRight size={14} color={colors.neutral3.val} />}
            {parsedCollateral > 0 && <Text variant="body3" color="$neutral1">
                {totalCollateral.toFixed(4)}
              </Text>}
          </Flex>
        </InfoRow>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center" gap="$gap8">
            <PortfolioLogo
    chainId={chainId}
    tokenSymbol={borrowToken.symbol}
    tokenName={borrowToken.symbol ?? ""}
    images={[getTokenLogoUrl(borrowToken.id)]}
    size={20}
  />
            <Text variant="body3" color="$neutral2">
              Loan ({borrowToken.symbol})
            </Text>
          </Flex>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body3" color="$neutral2">
              {existingLoan.toFixed(4)}
            </Text>
            {parsedBorrow > 0 && <ArrowRight size={14} color={colors.neutral3.val} />}
            {parsedBorrow > 0 && <Text variant="body3" color="$neutral1">
                {totalBorrow.toFixed(4)}
              </Text>}
          </Flex>
        </InfoRow>

        <InfoRow>
          <Text variant="body3" color="$neutral2">
            LTV
          </Text>
          <Flex flexDirection="row" alignItems="center" gap="$gap4">
            <Text variant="body3" color="$neutral2">
              {currentLtv.toFixed(2)}%
            </Text>
            {(parsedCollateral > 0 || parsedBorrow > 0) && <ArrowRight size={14} color={colors.neutral3.val} />}
            {(parsedCollateral > 0 || parsedBorrow > 0) && <Text variant="body3" color={projectedLtv > liquidationLtv ? "$statusCritical" : "$neutral1"}>
                {projectedLtv.toFixed(2)}%
              </Text>}
          </Flex>
        </InfoRow>

        <InfoRow>
          <Flex flexDirection="row" alignItems="center">
            <Text variant="body3" color="$neutral2">
              Liquidation LTV
            </Text>
            <ShieldIcon>
              <Shield size={10} color={colors.neutral2.val} fill={colors.neutral2.val} />
            </ShieldIcon>
          </Flex>
          <Text variant="body3" color="$neutral1">
            {liquidationLtv}%
          </Text>
        </InfoRow>

        <InfoRow style={{ marginBottom: 0 }}>
          <Text variant="body3" color="$neutral2">
            Rate
          </Text>
          <Text variant="body3" color="$neutral1">
            {rate.toFixed(2)}%
          </Text>
        </InfoRow>
      </Card>

      {validationError && <Flex
    backgroundColor={validationError.type === "critical" ? "$statusCritical" : "$statusWarning"}
    opacity={0.1}
    borderRadius="$rounded12"
    p="$spacing12"
    mb="$spacing8"
  >
          <Text variant="body4" color={validationError.type === "critical" ? "$statusCritical" : "$statusWarning"}>
            {validationError.message}
          </Text>
        </Flex>}

      <ActionButton
    disabled={!isFormValid || hasValidationError}
    onPress={() => setIsReviewOpen(true)}
  >
        <Button.Text>{validationError ? validationError.message : actionText}</Button.Text>
      </ActionButton>

      <BorrowReviewModal
    isOpen={isReviewOpen}
    onClose={() => setIsReviewOpen(false)}
    onConfirm={handleConfirm}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={collateralToken}
    borrowToken={borrowToken}
    transactionType={activeTab}
    currentHealthFactor={currentHealthFactor}
    projectedHealthFactor={projectedHealthFactor}
    currentLtv={currentLtv}
    projectedLtv={projectedLtv}
    currentCollateral={existingCollateral}
    currentBorrow={existingLoan}
    borrowRate={marketData.borrowRate}
    lltvPercent={marketData.lltvPercent}
  />

      <BorrowConfirmModal
    isOpen={isConfirmOpen}
    onClose={() => setIsConfirmOpen(false)}
    marketId={marketData.id}
    collateralAmount={collateralAmount}
    borrowAmount={borrowAmount}
    collateralToken={collateralToken}
    borrowToken={borrowToken}
    lltvPercent={marketData.lltvPercent}
    transactionType={activeTab}
    currentHealthFactor={currentHealthFactor}
    projectedHealthFactor={projectedHealthFactor}
  />
    </Container>;
}
